#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct Cube {
    /// Piece index at each corner position.
    pub cp: [u8; 8],
    /// Twist of the piece at each corner position, `0..3`.
    pub co: [u8; 8],
    /// Piece index at each edge position.
    pub ep: [u8; 12],
    /// Flip of the piece at each edge position, `0..2`.
    pub eo: [u8; 12],
}

#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct Move(pub u8);

#[repr(u8)]
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Color {
    /// Up: white.
    U = 0,
    /// Down: yellow.
    D = 1,
    /// Front: green.
    F = 2,
    /// Back: blue.
    B = 3,
    /// Right: red.
    R = 4,
    /// Left: orange.
    L = 5,
}

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub struct Scramble {
    /// The moves of the walk, in application order.
    pub moves: [Move; MAX_SCRAMBLE_LEN],
    /// Number of live entries in `moves`.
    pub len: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum CubeError {
    /// The 54 facelets do not contain exactly nine stickers of each colour.
    MalformedFacelets,
    /// The six centre stickers are not the fixed solved centres.
    InvalidCenter,
    /// A corner or edge piece is missing, unrecognisable, or duplicated.
    InvalidPermutation,
    /// The corner twist sum is not divisible by three.
    Twist,
    /// The edge flip sum is not even.
    Flip,
    /// Corner and edge permutation parities differ.
    Parity,
}

/// A solver result.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Solution {
    /// The moves in application order.
    pub moves: Vec<Move>,
    /// Whether the solver claims optimality. Both v1 solvers always return
    /// `false`.
    pub optimal: bool,
    /// Two-phase split point; `None` for single-strategy solvers.
    pub phases: Option<[usize; 2]>,
}

/// Stage limits for a solver.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Limits {
    /// Maximum combined solution length.
    pub max_length: Option<u8>,
    /// Wall-clock budget in milliseconds. `Some(0)` times out before search.
    pub time_ms: Option<u32>,
}

#[must_use]
pub fn cp_rank(cube: &Cube) -> u16 {
    lehmer_rank(&cube.cp) as u16
}

#[must_use]
pub fn ep8_rank(cube: &Cube) -> u16 {
    assert!(is_g1(cube), "ep8 is undefined outside G1");
    let mut permutation = [0u8; 8];
    permutation.copy_from_slice(&cube.ep[..8]);
    lehmer_rank(&permutation) as u16
}

#[must_use]
pub fn sp_rank(cube: &Cube) -> u16 {
    assert!(is_g1(cube), "sp is undefined outside G1");
    let mut permutation = [0u8; 4];
    for (slot, &piece) in permutation.iter_mut().zip(&cube.ep[8..]) {
        *slot = piece - 8;
    }
    lehmer_rank(&permutation) as u16
}
